import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.D9E58p8B.js";const p=JSON.parse('{"title":"Mise à jour","description":"","frontmatter":{"title":"Mise à jour"},"headers":[],"relativePath":"guide/mise-a-jour.md","filePath":"guide/mise-a-jour.md"}'),r={name:"guide/mise-a-jour.md"};function o(n,e,l,d,u,c){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="mise-a-jour" tabindex="-1">Mise à jour <a class="header-anchor" href="#mise-a-jour" aria-label="Permalink to &quot;Mise à jour&quot;">​</a></h1><h2 id="comment-ca-se-passe" tabindex="-1">Comment ça se passe <a class="header-anchor" href="#comment-ca-se-passe" aria-label="Permalink to &quot;Comment ça se passe&quot;">​</a></h2><p>Daimon vérifie s&#39;il existe une nouvelle version au lancement, à l&#39;ouverture de son panneau, et une fois par jour, et l&#39;affiche dans le panneau.</p><ul><li><strong>Rien ne s&#39;installe</strong> tant que vous n&#39;avez pas cliqué sur <strong>Mettre à jour vers la v…</strong>.</li><li>La signature de chaque mise à jour est vérifiée avant qu&#39;elle ne remplace l&#39;application.</li><li>Pendant l&#39;installation, le panneau l&#39;indique ; si une recherche ou une installation échoue, il en affiche la raison.</li></ul><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><p>Le bouton <strong>Mettre à jour</strong> installe la nouvelle version. Vous pouvez aussi la télécharger depuis la <a href="https://github.com/ArboRithm/Daimon/releases/latest" target="_blank" rel="noreferrer">page des releases</a>.</p><h2 id="regler-ou-desactiver-la-verification" tabindex="-1">Régler ou désactiver la vérification <a class="header-anchor" href="#regler-ou-desactiver-la-verification" aria-label="Permalink to &quot;Régler ou désactiver la vérification&quot;">​</a></h2><p>Créez un fichier <code>update.yaml</code> dans le dossier de configuration (panneau › <strong>Ouvrir le dossier de configuration</strong>). Les clés lues par le code, sous <code>update:</code>, et leurs valeurs par défaut :</p><table tabindex="0"><thead><tr><th>Clé</th><th>Défaut</th><th>Sens</th></tr></thead><tbody><tr><td><code>enabled</code></td><td><code>true</code></td><td>Vérification automatique</td></tr><tr><td><code>interval_hours</code></td><td><code>24</code></td><td>Intervalle entre deux vérifications, en heures</td></tr><tr><td><code>auto_apply</code></td><td><code>false</code></td><td>Appliquer automatiquement</td></tr><tr><td><code>allow_prerelease</code></td><td><code>false</code></td><td>Accepter les préversions</td></tr><tr><td><code>channel</code></td><td>vide</td><td>Canal de mise à jour ; vide = celui de la version installée</td></tr></tbody></table><p>Pour désactiver la vérification automatique :</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><h2 id="reseau" tabindex="-1">Réseau <a class="header-anchor" href="#reseau" aria-label="Permalink to &quot;Réseau&quot;">​</a></h2><p>La vérification est la seule connexion à Internet de Daimon ; elle est servie par GitHub Releases. Voir <a href="./confidentialite.html">Confidentialité</a>.</p>`,13)])])}const m=a(r,[["render",o]]);export{p as __pageData,m as default};
